def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Returns the indices of horizontal and vertical aisles that maximize the number of separated
    chatting pairs.  The aisles are placed between rows/columns, so possible positions are
    1..M-1 for rows and 1..N-1 for columns.
    """
    # Validate inputs
    if M <= 0 or N <= 0:
        return ('', '')
    # Limit the number of aisles to maximum available positions
    max_row_cuts = max(M - 1, 0)
    max_col_cuts = max(N - 1, 0)
    K = min(K, max_row_cuts)
    L = min(L, max_col_cuts)

    # Edge cases: no aisles to place
    if K == 0 and L == 0:
        return ('', '')
    if not chatting_pairs:
        return ('', '')

    num_pairs = len(chatting_pairs)

    # Precompute which cuts separate each pair
    row_cut_to_pairs = {cut: set() for cut in range(1, M)}   # cuts between rows r and r+1 are at position r
    col_cut_to_pairs = {cut: set() for cut in range(1, N)}   # cuts between cols c and c+1 are at position c

    for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
        # Horizontal separation
        if x1 < x2:
            for cut in range(x1, x2):
                row_cut_to_pairs[cut].add(idx)
        elif x2 < x1:
            for cut in range(x2, x1):
                row_cut_to_pairs[cut].add(idx)
        # Vertical separation
        if y1 < y2:
            for cut in range(y1, y2):
                col_cut_to_pairs[cut].add(idx)
        elif y2 < y1:
            for cut in range(y2, y1):
                col_cut_to_pairs[cut].add(idx)

    from itertools import combinations

    best_coverage = -1
    best_rows = None
    best_cols = None

    # Enumerate all combinations of horizontal and vertical cuts
    row_positions = list(range(1, M))   # 1..M-1
    col_positions = list(range(1, N))   # 1..N-1

    for row_comb in combinations(row_positions, K):
        # union of pairs separated by chosen horizontal cuts
        covered_pairs = set()
        for cut in row_comb:
            covered_pairs.update(row_cut_to_pairs[cut])
        # For each vertical combination we'll compute additional coverage
        for col_comb in combinations(col_positions, L):
            total_covered = set(covered_pairs)
            for cut in col_comb:
                total_covered.update(col_cut_to_pairs[cut])
            coverage = len(total_covered)
            if coverage > best_coverage:
                best_coverage = coverage
                best_rows = row_comb
                best_cols = col_comb
            # tie-breaking: lexicographically smallest rows and then columns
            elif coverage == best_coverage:
                if row_comb < best_rows:
                    best_rows = row_comb
                    best_cols = col_comb
                elif row_comb == best_rows and col_comb < best_cols:
                    best_cols = col_comb

    # If no cuts result in coverage, return empty strings
    if best_rows is None:
        best_rows, best_cols = [], []

    row_str = ' '.join(str(r) for r in sorted(best_rows))
    col_str = ' '.join(str(c) for c in sorted(best_cols))

    return (row_str, col_str)

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    # Basic validation
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(coeffs, list):
        raise ValueError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError("coeffs length must be n + 1")
    for c in coeffs:
        if not isinstance(c, int):
            raise ValueError("All coefficients must be integers")

    parts: List[str] = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        deg = n - idx
        if coeff == 0:
            continue

        # Determine sign
        sign = ""
        if first_term:
            if coeff < 0:
                sign = "-"
        else:
            sign = "+" if coeff > 0 else "-"

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if deg == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = "" if abs_coeff == 1 else str(abs_coeff)

        # Determine variable part
        if deg > 1:
            var_str = f"x^{deg}"
        elif deg == 1:
            var_str = "x"
        else:
            var_str = ""

        parts.append(f"{sign}{coeff_str}{var_str}")
        first_term = False

    if not parts:
        return "0"

    return "".join(parts)

def select_volunteers(n: int, m: int, applicants):
    """
    Select volunteers based on score cutoff.

    Parameters
    ----------
    n : int
        Total number of applicants. (May be ignored if applicants list length differs.)
    m : int
        Planned number of volunteers to recruit.
    applicants : List[Tuple[int, int]]
        Each tuple contains (registration_number, test_score).

    Returns
    -------
    Tuple[int, List[Tuple[int, int]]]
        The score cutoff and a list of-qualified applicants sorted by score descending,
        then registration number ascending.
    """
    try:
        # Basic validation
        if not isinstance(n, int) or not isinstance(m, int):
            raise TypeError("n and m must be integers")
        if m < 0:
            raise ValueError("m must be non-negative")
        if not isinstance(applicants, list):
            raise TypeError("applicants must be a list")
        for a in applicants:
            if not (isinstance(a, tuple) or isinstance(a, list)) or len(a) != 2:
                raise TypeError("Each applicant must be a tuple/list of (reg_no, score)")
            reg, score = a
            if not isinstance(reg, int) or not isinstance(score, int):
                raise TypeError("registration number and score must be integers")
    except Exception:
        # If any validation fails, return empty result
        return (0, [])

    if not applicants:
        return (0, [])

    # Sort applicants: score descending, registration ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Compute cutoff count based on 150% of planned recruits, floor
    cutoff_count = int(m * 1.5)
    if cutoff_count == 0:
        # No cutoff, no qualified applicants
        return (0, [])

    # Adjust cutoff_count if it exceeds available applicants
    cutoff_index = min(cutoff_count, len(sorted_applicants)) - 1
    cutoff_score = sorted_applicants[cutoff_index][1]

    # Filter qualified applicants (score >= cutoff_score)
    qualified = [a for a in sorted_applicants if a[1] >= cutoff_score]

    return (cutoff_score, qualified)

